toolArgs.file_text:
.message-bubble {
    padding: 8px 16px;
    position: relative;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: #f8f9fa;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #212529;
}

.timestamp {
    font-size: 0.75rem;
    color: #868e96;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.45;
    color: #343a40;
    white-space: pre-wrap;
    word-break: break-word;
}

.reaction-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    background: #f1f3f5;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background-color 0.1s;
}

.reaction-badge:hover {
    background: #e2e6ea;
    border-color: #adb5bd;
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    padding: 2px 0;
    background: none;
    border: none;
    color: #0d6efd;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: 4px;
    right: 12px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
    padding: 2px;
}

.action-btn {
    background: none;
    border: none;
    padding: 4px 8px;
    font-size: 1rem;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

.action-btn:hover {
    background: #e9ecef;
}

.emoji-picker {
    display: flex;
    gap: 4px;
    padding: 6px 8px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    margin-top: 4px;
    width: fit-content;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.25rem;
    padding: 4px;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

.emoji-btn:hover {
    background: #e9ecef;
}

