@using sv_6a95dfea57fc4207916d19a68a56a591.Services
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-area">
    <div class="message-area-header">
        @if (Channel is not null)
        {
            <h2># @Channel.Name</h2>
            <p>@Channel.Description</p>
        }
    </div>

    <div class="message-list" @ref="messageListRef">
        @if (HasMoreMessages)
        {
            <div class="load-more-container">
                <button class="load-more-btn" @onclick="HandleLoadMore" disabled="@isLoadingMore">
                    @(isLoadingMore ? "Loading..." : "Load older messages")
                </button>
            </div>
        }
        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ThreadSummary="GetThreadSummary(message.Id)"
                           OnReplyClicked="() => OnOpenThread.InvokeAsync(message.Id)"
                           OnReactionAdded="(emoji) => OnReactionAdded.InvokeAsync((message.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel?.Name ?? "channel"}")"
                  ButtonText="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = new();
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactionAdded { get; set; }

    private ElementReference messageListRef;
    private DotNetObjectReference<MessageArea>? dotNetRef;
    private bool isLoadingMore;
    private bool hasInitialized;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            await JS.InvokeVoidAsync("chatScroll.initScrollTopObserver", messageListRef, dotNetRef);
            await JS.InvokeVoidAsync("chatScroll.scrollToBottom", messageListRef);
            hasInitialized = true;
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (HasMoreMessages && !isLoadingMore)
        {
            isLoadingMore = true;
            StateHasChanged();
            await OnLoadMore.InvokeAsync();
            isLoadingMore = false;
            StateHasChanged();
        }
    }

    private async Task HandleLoadMore()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;
        await OnLoadMore.InvokeAsync();
        isLoadingMore = false;
    }

    private ThreadSummary? GetThreadSummary(int messageId) =>
        ThreadSummaries.GetValueOrDefault(messageId);

    public async Task ScrollToBottomAsync()
    {
        if (hasInitialized)
        {
            await JS.InvokeVoidAsync("chatScroll.scrollToBottom", messageListRef);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (hasInitialized)
        {
            try
            {
                await JS.InvokeVoidAsync("chatScroll.disposeScrollTopObserver", messageListRef);
            }
            catch (JSDisconnectedException)
            {
                // Circuit disconnected; safe to ignore
            }
        }
        dotNetRef?.Dispose();
    }
}

