arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_6a95dfea57fc4207916d19a68a56a591.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(isThreadOpen ? "with-thread" : "")">
        <MessageArea @ref="messageArea"
                     Channel="selectedChannel"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     HasMoreMessages="hasMoreMessages"
                     OnLoadMore="LoadMoreMessages"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReactionAdded="AddReaction" />
    </div>

    @if (isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = new();
    private Channel? selectedChannel;
    private int? selectedChannelId;
    private List<Message> messages = new();
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private bool hasMoreMessages = true;
    private const int PageSize = 50;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    private MessageArea? messageArea;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = new List<Message>();
        threadSummaries = new Dictionary<int, ThreadSummary>();
        hasMoreMessages = true;
        CloseThread();

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channelId);

        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages()
    {
        if (selectedChannelId is null) return;
        var batch = await ChatService.GetMessagesAsync(selectedChannelId.Value, messages.Count, PageSize);
        if (batch.Count < PageSize) hasMoreMessages = false;
        messages.InsertRange(0, batch);
        BuildThreadSummaries();
    }

    private async Task LoadMoreMessages()
    {
        await LoadMessages();
    }

    private void BuildThreadSummaries()
    {
        threadSummaries.Clear();
        var replies = messages.Where(m => m.ReplyToId.HasValue).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(msg);
        if (messageArea is not null)
        {
            await messageArea.ScrollToBottomAsync();
        }
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = new List<Message>();
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        if (threadSummaries.TryGetValue(threadRootMessage.Id, out var summary))
        {
            threadSummaries[threadRootMessage.Id] = summary with
            {
                ReplyCount = summary.ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            threadSummaries[threadRootMessage.Id] = new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt);
        }
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        var msgIndex = messages.FindIndex(m => m.Id == args.MessageId);
        if (msgIndex >= 0)
        {
            var msg = messages[msgIndex];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                reactions[existing] = r with { Users = [.. r.Users, "You"] };
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            messages[msgIndex] = msg with { Reactions = reactions };
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 300px;
    border-right: 1px solid #e0e0e0;
    background: #f8f9fa;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    border-left: 1px solid #e0e0e0;
    flex-shrink: 0;
}

