toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 300px;
    border-right: 1px solid #e0e0e0;
    background: #f8f9fa;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    border-left: 1px solid #e0e0e0;
    flex-shrink: 0;
}

